-- Trade Time
cboe_dxederivatives_binaryorderentry_boe_v2_18.trade_time = {}

-- Size: Trade Time
cboe_dxederivatives_binaryorderentry_boe_v2_18.trade_time.size = 8

-- Display: Trade Time
cboe_dxederivatives_binaryorderentry_boe_v2_18.trade_time.display = function(value)
  -- Parse unix nanosecond timestamp
  local seconds = (value / UInt64(1000000000)):tonumber()
  local nanoseconds = (value % UInt64(1000000000)):tonumber()

  return "Trade Time: "..os.date("%Y-%m-%d %H:%M:%S.", seconds)..string.format("%09d", nanoseconds)
end

-- Dissect: Trade Time
cboe_dxederivatives_binaryorderentry_boe_v2_18.trade_time.dissect = function(buffer, offset, packet, parent)
  local length = cboe_dxederivatives_binaryorderentry_boe_v2_18.trade_time.size
