cboe_dxederivatives_binaryorderentry_boe_v2_18.complex_instrument_accepted_return_bitfield_18.display = function(range, value, packet, parent)
  local flags = {}

  -- Is Complex Instrument Accepted Return Bitfield 18 Account Type flag set?
  if bit.band(value, 0x01) ~= 0 then
    flags[#flags + 1] = "Complex Instrument Accepted Return Bitfield 18 Account Type"
  end
  -- Is Complex Instrument Accepted Return Bitfield 18 Cross Initiator flag set?
  if bit.band(value, 0x02) ~= 0 then
    flags[#flags + 1] = "Complex Instrument Accepted Return Bitfield 18 Cross Initiator"
  end
  -- Is Complex Instrument Accepted Return Bitfield 18 Subreason flag set?
  if bit.band(value, 0x04) ~= 0 then
    flags[#flags + 1] = "Complex Instrument Accepted Return Bitfield 18 Subreason"
  end
  -- Is Complex Instrument Accepted Return Bitfield 18 Reserved 8 flag set?
  if bit.band(value, 0x08) ~= 0 then
    flags[#flags + 1] = "Complex Instrument Accepted Return Bitfield 18 Reserved 8"
  end
  -- Is Complex Instrument Accepted Return Bitfield 18 Leg Price flag set?
  if bit.band(value, 0x10) ~= 0 then
    flags[#flags + 1] = "Complex Instrument Accepted Return Bitfield 18 Leg Price"
  end
  -- Is Complex Instrument Accepted Return Bitfield 18 Reserved 32 flag set?
  if bit.band(value, 0x20) ~= 0 then
    flags[#flags + 1] = "Complex Instrument Accepted Return Bitfield 18 Reserved 32"
  end
  -- Is Complex Instrument Accepted Return Bitfield 18 Reserved 64 flag set?
  if bit.band(value, 0x40) ~= 0 then
    flags[#flags + 1] = "Complex Instrument Accepted Return Bitfield 18 Reserved 64"
  end
  -- Is Complex Instrument Accepted Return Bitfield 18 Reserved 128 flag set?
  if bit.band(value, 0x80) ~= 0 then
    flags[#flags + 1] = "Complex Instrument Accepted Return Bitfield 18 Reserved 128"
  end

  return table.concat(flags, "|")
end

