cboe_dxederivatives_binaryorderentry_boe_v2_18.quote_restated_message = {}

-- Read runtime size of: Quote Restated Message
cboe_dxederivatives_binaryorderentry_boe_v2_18.quote_restated_message.size = function(buffer, offset)
  local index = offset

  -- Dependency element: Message Length
  local message_length = buffer(offset - 8, 2):le_uint()

  return message_length - 8
end

-- Display: Quote Restated Message
cboe_dxederivatives_binaryorderentry_boe_v2_18.quote_restated_message.display = function(packet, parent, length)
  return ""
end

-- Dissect Fields: Quote Restated Message
cboe_dxederivatives_binaryorderentry_boe_v2_18.quote_restated_message.fields = function(buffer, offset, packet, parent, size_of_quote_restated_message)
  local index = offset

  -- Transaction Time: DateTime
  index, transaction_time = cboe_dxederivatives_binaryorderentry_boe_v2_18.transaction_time.dissect(buffer, index, packet, parent)

  -- Quote Update Id: Text
  index, quote_update_id = cboe_dxederivatives_binaryorderentry_boe_v2_18.quote_update_id.dissect(buffer, index, packet, parent)

  -- Order Id: Binary
  index, order_id = cboe_dxederivatives_binaryorderentry_boe_v2_18.order_id.dissect(buffer, index, packet, parent)

  -- Leaves Qty: Binary
  index, leaves_qty = cboe_dxederivatives_binaryorderentry_boe_v2_18.leaves_qty.dissect(buffer, index, packet, parent)

  -- Working Price: BinaryPrice
  index, working_price = cboe_dxederivatives_binaryorderentry_boe_v2_18.working_price.dissect(buffer, index, packet, parent)

  -- Symbol Alphanumeric 6: Alphanumeric
  index, symbol_alphanumeric_6 = cboe_dxederivatives_binaryorderentry_boe_v2_18.symbol_alphanumeric_6.dissect(buffer, index, packet, parent)

  -- Side: Alphanumeric
  index, side = cboe_dxederivatives_binaryorderentry_boe_v2_18.side.dissect(buffer, index, packet, parent)

  -- Restatement Reason: Alphanumeric
  index, restatement_reason = cboe_dxederivatives_binaryorderentry_boe_v2_18.restatement_reason.dissect(buffer, index, packet, parent)

  return index
end

-- Dissect: Quote Restated Message
cboe_dxederivatives_binaryorderentry_boe_v2_18.quote_restated_message.dissect = function(buffer, offset, packet, parent, size_of_quote_restated_message)
  local size_of_quote_restated_message = cboe_dxederivatives_binaryorderentry_boe_v2_18.quote_restated_message.size(buffer, offset)
  local index = offset + size_of_quote_restated_message

  -- Optionally add group/struct element to protocol tree
  if show.application_messages then
    parent = parent:add(omi_cboe_dxederivatives_binaryorderentry_boe_v2_18.fields.quote_restated_message, buffer(offset, 0))
    local current = cboe_dxederivatives_binaryorderentry_boe_v2_18.quote_restated_message.fields(buffer, offset, packet, parent, size_of_quote_restated_message)
    parent:set_len(size_of_quote_restated_message)
    local display = cboe_dxederivatives_binaryorderentry_boe_v2_18.quote_restated_message.display(buffer, packet, parent)
    parent:append_text(display)

    return index, parent
  else
    -- Skip element, add fields directly
    cboe_dxederivatives_binaryorderentry_boe_v2_18.quote_restated_message.fields(buffer, offset, packet, parent, size_of_quote_restated_message)

    return index
  end
end

