-- Dissect Fields: Purge Orders Message
cboe_dxederivatives_binaryorderentry_boe_v2_18.purge_orders_message.fields = function(buffer, offset, packet, parent, size_of_purge_orders_message)
  local index = offset

  -- Reserved 1: Reserved
  index, reserved_1 = cboe_dxederivatives_binaryorderentry_boe_v2_18.reserved_1.dissect(buffer, index, packet, parent)

  -- Number Of Purge Orders Bitfields: Binary
  index, number_of_purge_orders_bitfields = cboe_dxederivatives_binaryorderentry_boe_v2_18.number_of_purge_orders_bitfields.dissect(buffer, index, packet, parent)

  -- Runtime optional field: Purge Orders Bitfield 1
  local purge_orders_bitfield_1 = nil

  local purge_orders_bitfield_1_exists = number_of_purge_orders_bitfields >= 1

  if purge_orders_bitfield_1_exists then

    -- Purge Orders Bitfield 1: Struct of 8 fields
    index, purge_orders_bitfield_1 = cboe_dxederivatives_binaryorderentry_boe_v2_18.purge_orders_bitfield_1.dissect(buffer, index, packet, parent)
  end

  -- Runtime optional field: Purge Orders Bitfield 2
  local purge_orders_bitfield_2 = nil

  local purge_orders_bitfield_2_exists = number_of_purge_orders_bitfields >= 2

  if purge_orders_bitfield_2_exists then

    -- Purge Orders Bitfield 2: Struct of 8 fields
    index, purge_orders_bitfield_2 = cboe_dxederivatives_binaryorderentry_boe_v2_18.purge_orders_bitfield_2.dissect(buffer, index, packet, parent)
  end

  -- Custom Group Id Cnt: Binary
  index, custom_group_id_cnt = cboe_dxederivatives_binaryorderentry_boe_v2_18.custom_group_id_cnt.dissect(buffer, index, packet, parent)

  -- Repeating: Custom Group Ids
  for custom_group_ids_index = 1, custom_group_id_cnt do
    index, custom_group_ids = cboe_dxederivatives_binaryorderentry_boe_v2_18.custom_group_ids.dissect(buffer, index, packet, parent, custom_group_ids_index)
  end

  -- Runtime optional field: Clearing Firm
  local clearing_firm = nil

  local clearing_firm_exists = number_of_purge_orders_bitfields >= 1 and bit.band(purge_orders_bitfield_1, 0x01) > 0

  if clearing_firm_exists then
    index, clearing_firm = cboe_dxederivatives_binaryorderentry_boe_v2_18.clearing_firm.dissect(buffer, index, packet, parent)
  end

  -- Runtime optional field: Product Code
  local product_code = nil

  local product_code_exists = number_of_purge_orders_bitfields >= 1 and bit.rshift(bit.band(purge_orders_bitfield_1, 0x08), 3) > 0

  if product_code_exists then
    index, product_code = cboe_dxederivatives_binaryorderentry_boe_v2_18.product_code.dissect(buffer, index, packet, parent)
  end

  -- Runtime optional field: Mass Cancel Id
  local mass_cancel_id = nil

  local mass_cancel_id_exists = number_of_purge_orders_bitfields >= 1 and bit.rshift(bit.band(purge_orders_bitfield_1, 0x10), 4) > 0

  if mass_cancel_id_exists then
    index, mass_cancel_id = cboe_dxederivatives_binaryorderentry_boe_v2_18.mass_cancel_id.dissect(buffer, index, packet, parent)
  end

  return index
end

