  if quote_index ~= nil and show.indexes then
    local iteration = parent:add(omi_cboe_dxederivatives_binaryorderentry_boe_v2_18.fields.quote_index, quote_index)
    iteration:set_generated()
  end

  -- Symbol Alphanumeric 6: Alphanumeric
