  index, side = cboe_dxederivatives_binaryorderentry_boe_v2_18.side.dissect(buffer, index, packet, parent)

  -- Open Close: Alphanumeric
  index, open_close = cboe_dxederivatives_binaryorderentry_boe_v2_18.open_close.dissect(buffer, index, packet, parent)

  -- Price: BinaryPrice
  index, price = cboe_dxederivatives_binaryorderentry_boe_v2_18.price.dissect(buffer, index, packet, parent)

  -- Order Qty: Binary
  index, order_qty = cboe_dxederivatives_binaryorderentry_boe_v2_18.order_qty.dissect(buffer, index, packet, parent)

  return index
