-- Dissect: Quote
cboe_dxederivatives_binaryorderentry_boe_v2_18.quote.dissect = function(buffer, offset, packet, parent, quote_index)
  if show.repeating_groups then
    -- Optionally add element to protocol tree
    parent = parent:add(omi_cboe_dxederivatives_binaryorderentry_boe_v2_18.fields.quote, buffer(offset, 0))
    local index = cboe_dxederivatives_binaryorderentry_boe_v2_18.quote.fields(buffer, offset, packet, parent, quote_index)
    local length = index - offset
    parent:set_len(length)
    local display = cboe_dxederivatives_binaryorderentry_boe_v2_18.quote.display(packet, parent, length)
    parent:append_text(display)

    return index, parent
  else
    -- Skip element, add fields directly
    return cboe_dxederivatives_binaryorderentry_boe_v2_18.quote.fields(buffer, offset, packet, parent, quote_index)
  end
end

