-- Dissect: New Order V 2 Message
cboe_dxederivatives_binaryorderentry_boe_v2_18.new_order_v_2_message.dissect = function(buffer, offset, packet, parent, size_of_new_order_v_2_message)
  local size_of_new_order_v_2_message = cboe_dxederivatives_binaryorderentry_boe_v2_18.new_order_v_2_message.size(buffer, offset)
  local index = offset + size_of_new_order_v_2_message

  -- Optionally add group/struct element to protocol tree
  if show.application_messages then
    parent = parent:add(omi_cboe_dxederivatives_binaryorderentry_boe_v2_18.fields.new_order_v_2_message, buffer(offset, 0))
    local current = cboe_dxederivatives_binaryorderentry_boe_v2_18.new_order_v_2_message.fields(buffer, offset, packet, parent, size_of_new_order_v_2_message)
    parent:set_len(size_of_new_order_v_2_message)
    local display = cboe_dxederivatives_binaryorderentry_boe_v2_18.new_order_v_2_message.display(buffer, packet, parent)
    parent:append_text(display)

    return index, parent
  else
    -- Skip element, add fields directly
    cboe_dxederivatives_binaryorderentry_boe_v2_18.new_order_v_2_message.fields(buffer, offset, packet, parent, size_of_new_order_v_2_message)

    return index
  end
end

