    local iteration = parent:add(omi_cboe_dxederivatives_binaryorderentry_boe_v2_18.fields.units_index, units_index)
    iteration:set_generated()
  end

  -- Unit Number: Binary
  index, unit_number = cboe_dxederivatives_binaryorderentry_boe_v2_18.unit_number.dissect(buffer, index, packet, parent)

  -- Unit Sequence: Binary
  index, unit_sequence = cboe_dxederivatives_binaryorderentry_boe_v2_18.unit_sequence.dissect(buffer, index, packet, parent)

  return index
end

-- Dissect: Units
