  if show.repeating_groups then
    -- Optionally add element to protocol tree
    parent = parent:add(omi_cboe_dxederivatives_binaryorderentry_boe_v2_18.fields.units, buffer(offset, 0))
    local index = cboe_dxederivatives_binaryorderentry_boe_v2_18.units.fields(buffer, offset, packet, parent, units_index)
    local length = index - offset
    parent:set_len(length)
    local display = cboe_dxederivatives_binaryorderentry_boe_v2_18.units.display(packet, parent, length)
    parent:append_text(display)

    return index, parent
  else
    -- Skip element, add fields directly
    return cboe_dxederivatives_binaryorderentry_boe_v2_18.units.fields(buffer, offset, packet, parent, units_index)
  end
