end

-- Dissect Fields: Logout Message
cboe_dxederivatives_binaryorderentry_boe_v2_18.logout_message.fields = function(buffer, offset, packet, parent, size_of_logout_message)
  local index = offset

  -- Logout Reason: Alphanumeric
  index, logout_reason = cboe_dxederivatives_binaryorderentry_boe_v2_18.logout_reason.dissect(buffer, index, packet, parent)

  -- Logout Reason Text: Text
  index, logout_reason_text = cboe_dxederivatives_binaryorderentry_boe_v2_18.logout_reason_text.dissect(buffer, index, packet, parent)

  -- Last Received Sequence Number: Binary
  index, last_received_sequence_number = cboe_dxederivatives_binaryorderentry_boe_v2_18.last_received_sequence_number.dissect(buffer, index, packet, parent)

  -- Number Of Units: Binary
  index, number_of_units = cboe_dxederivatives_binaryorderentry_boe_v2_18.number_of_units.dissect(buffer, index, packet, parent)

  -- Repeating: Units
  for units_index = 1, number_of_units do
    index, units = cboe_dxederivatives_binaryorderentry_boe_v2_18.units.dissect(buffer, index, packet, parent, units_index)
  end

  return index
