    -- Optionally add element to protocol tree
    parent = parent:add(omi_cboe_dxederivatives_binaryorderentry_boe_v2_18.fields.message_header, buffer(offset, 0))
    local index = cboe_dxederivatives_binaryorderentry_boe_v2_18.message_header.fields(buffer, offset, packet, parent)
    local length = index - offset
    parent:set_len(length)
    local display = cboe_dxederivatives_binaryorderentry_boe_v2_18.message_header.display(packet, parent, length)
    parent:append_text(display)

    return index, parent
  else
    -- Skip element, add fields directly
    return cboe_dxederivatives_binaryorderentry_boe_v2_18.message_header.fields(buffer, offset, packet, parent)
  end
end

-- Packet
cboe_dxederivatives_binaryorderentry_boe_v2_18.packet = {}

-- Verify required size of Tcp packet
cboe_dxederivatives_binaryorderentry_boe_v2_18.packet.requiredsize = function(buffer)
  return buffer:len() >= cboe_dxederivatives_binaryorderentry_boe_v2_18.message_header.size
end

-- Dissect Packet
cboe_dxederivatives_binaryorderentry_boe_v2_18.packet.dissect = function(buffer, packet, parent)
  local index = 0

  -- Message Header: Struct of 5 fields
  index, message_header = cboe_dxederivatives_binaryorderentry_boe_v2_18.message_header.dissect(buffer, index, packet, parent)

  -- Dependency element: Message Type
  local message_type = buffer(index - 6, 1):le_uint()

  -- Message: Runtime Type with 44 branches
  index = cboe_dxederivatives_binaryorderentry_boe_v2_18.message.dissect(buffer, index, packet, parent, message_type)

  return index
end


