-- Initialize Dissector
function omi_cboe_dxederivatives_binaryorderentry_boe_v2_18.init()
end

-- Dissector for Cboe DxeDerivatives BinaryOrderEntry Boe 2.18
function omi_cboe_dxederivatives_binaryorderentry_boe_v2_18.dissector(buffer, packet, parent)
  -- Set protocol name
  packet.cols.protocol = omi_cboe_dxederivatives_binaryorderentry_boe_v2_18.name

  local length = buffer:len()
  local index = 0

  -- Dissect each message the segment carries
  while index < length do
    local remaining = length - index

    -- The message length lives in the header: wait for the header before reading it
    if remaining < cboe_dxederivatives_binaryorderentry_boe_v2_18.message_header.size then
      packet.desegment_offset = index
      packet.desegment_len = DESEGMENT_ONE_MORE_SEGMENT
      return length
    end

    local size = buffer(index + 2, 2):le_uint() + 2
    -- A message split across segments: ask TCP for exactly the bytes still missing
    if remaining < size then
      packet.desegment_offset = index
      packet.desegment_len = size - remaining
      return length
    end

    local protocol = parent:add(omi_cboe_dxederivatives_binaryorderentry_boe_v2_18, buffer(index, size), omi_cboe_dxederivatives_binaryorderentry_boe_v2_18.description, "("..size.." Bytes)")
    cboe_dxederivatives_binaryorderentry_boe_v2_18.packet.dissect(buffer(index, size):tvb(), packet, protocol)
    protocol:set_len(size)
    index = index + size
  end

  return index
end


