-- Dissector Heuristic for Cboe DxeDerivatives BinaryOrderEntry Boe 2.18 (Tcp)
local function omi_cboe_dxederivatives_binaryorderentry_boe_v2_18_tcp_heuristic(buffer, packet, parent)
  -- Verify packet length
  if not cboe_dxederivatives_binaryorderentry_boe_v2_18.packet.requiredsize(buffer) then return false end

  -- Protocol is valid, set conversation and dissect this packet
  packet.conversation = omi_cboe_dxederivatives_binaryorderentry_boe_v2_18
  omi_cboe_dxederivatives_binaryorderentry_boe_v2_18.dissector(buffer, packet, parent)

  return true
end

